  const installedRecovery=s.state==='recovery'?{enabled:true,mode:'two',helpers:['bootstrap-a.example','bootstrap-b.example']}:newRecovery();
  setPresentation(shown);setRefreshOutcome(shown.refreshOutcome);setCopyState('');
  setScene(s.id);setTab(s.tab);setStatus(s.state||'tracking');setProfile(p);setAppliedProfile(p);setSources(s.draft?[...base,extraSource()]:base);setAppliedSources(base);setModal(s.modal||null);
  const initialForm={...newSource(p),host:s.invalid?'https://time.example.org/path':''};sourceFormSnapshot.current={...initialForm};
  setSelected(s.details?'delta':'alpha');setExpanded(s.details?'delta':null);setPolicyOpen(Boolean(s.policy));setForm(initialForm);setErrors(s.invalid?{host:'Enter a hostname or IP address, without https:// or a path.'}:{});
  setOutcome(s.outcome||'success');setToast('');setLastAction('');setClosed(false);setObserve(Boolean(shown.observe));setAppliedObserve(Boolean(shown.observe));setRecovery(copyRecovery(installedRecovery));setAppliedRecovery(copyRecovery(installedRecovery));setRecoveryEditor(copyRecovery(installedRecovery));setRecoveryError('');setMaintenanceState('ready');setCorrectionExpired(Boolean(s.expiredProposal));
