 useEffect(()=>{loadScene(initial.id);},[]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),5000);return()=>clearTimeout(t);},[toast]);
 function openModal(name){focusBeforeDialog.current=document.activeElement;if(name==='recovery'){setRecoveryEditor(copyRecovery(recovery));setRecoveryError('');}setModal(name);}
 function closeModal(){setModal(null);requestAnimationFrame(()=>{const target=focusBeforeDialog.current?.isConnected?focusBeforeDialog.current:document.querySelector('.app-tabs .active');target?.focus?.();});}
 function requestCloseEditor(){if(JSON.stringify(form)!==JSON.stringify(sourceFormSnapshot.current)){setDiscardTarget('editor');setModal('discard');}else closeModal();}
