  const result=validateSource(form,sources,profile);setErrors(result.errors);
  if(Object.keys(result.errors).length){requestAnimationFrame(()=>document.querySelector('[aria-invalid="true"]')?.focus());return;}
  if(form.id&&!sourceReviewChanges(sources.find(s=>s.id===form.id),{...form,host:result.host}).length){closeModal();return;}
  const entry={...form,host:result.host,id:form.id||'new-'+Date.now(),role:'Pending',age:'—',lastValidReplyAge:'Not available',lastAcceptedMeasurementAge:'Not available',packetAuthentication:'Not established',certificateTimeBasis:'Not established',timeEndpoint:'Not established',offset:'—',delay:'—',uncertainty:'—',reason:'Draft change; not used by the service yet.'};
